export function articleSections(page) { return pageArticles[page]?.modules.map(id => ({ id, title: sections[id][0], paragraphs: sections[id][1].split('\n\n'), link: sections[id][2] })) || []; }
export function articleCharacterCount(page) { const a = pageArticles[page]; return a ? [a.title, a.intro, ...articleSections(page).flatMap(s => [s.title, ...s.paragraphs])].join(' ').length : 0; }
